    /** 取某个家具的碰撞箱；未登记的退化为整块。 */
    public static VoxelShape get(String id) {
        VoxelShape cached = CACHE.get(id);
        if (cached != null) {
            return cached;
        }
        VoxelShape built = build(id);
        CACHE.put(id, built);
        return built;
    }

    private static VoxelShape build(String id) {
        double[] b = BOXES.get(id);
        if (b == null) {
            return Shapes.block();
        }
        VoxelShape shape = Shapes.empty();
        for (int i = 0; i + 5 < b.length; i += 6) {
            VoxelShape one = Shapes.box(b[i], b[i + 1], b[i + 2], b[i + 3], b[i + 4], b[i + 5]);
            shape = Shapes.joinUnoptimized(shape, one, BooleanOp.OR);
        }
        return shape.optimize();
    }

